mapper.select:
SELECT enabled_value AS enabled, reason_text AS reason
FROM mk_journey_runtime_kill_switch
WHERE tenant_id = #{tenantId} AND namespace_name = #{namespace}

SELECT generation.generation_no AS generation, activation.activation_sequence AS activationSequence,
       activation.directive_json AS directiveJson, generation.release_key_id AS releaseKeyId,
       generation.manifest_json AS manifestJson, generation.artifact_payload AS payload,
       generation.artifact_id AS artifactId
FROM mk_journey_runtime_generation generation
JOIN mk_journey_runtime_activation activation ON activation.tenant_id = generation.tenant_id
  AND activation.environment_name = generation.environment_name AND activation.cell_id = generation.cell_id
  AND activation.namespace_name = generation.namespace_name AND activation.generation_no = generation.generation_no
WHERE generation.tenant_id = #{tenantId} AND generation.environment_name = #{environment}
  AND generation.cell_id = #{cell} AND generation.namespace_name = #{namespace}
  AND generation.generation_no = #{generation} AND activation.activation_sequence = #{sequence}
  AND generation.artifact_id = #{artifactId}
